 "food": {"kind": "", "time": "", "note": "",
   "items": [{"name": "", "grams": 0, "kcal": 0, "protein": 0, "fat": 0,
     "carbs": 0, "fiber": 0, "sure": ""}]},
 "feel": {"feel": 0, "knee": "", "note": ""},
 "question": "",
 "note": ""}
